class Solution {
  public long maximumSum(int[] nums, int m, int l, int r) {
    int n = nums.length;
    long NEG = Long.MIN_VALUE / 4;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    long[][] dp = new long[m + 1][n + 1];
    for (int j = 1; j <= m; j++) java.util.Arrays.fill(dp[j], NEG);
    long best = NEG;
    for (int j = 1; j <= m; j++) {
      int[] dq = new int[n + 2];
      int head = 0, tail = 0;
      for (int i = 1; i <= n; i++) {
        int add = i - l;
        if (add >= 0 && dp[j - 1][add] > NEG) {
          long val = dp[j - 1][add] - pre[add];
          while (tail > head && dp[j - 1][dq[tail - 1]] - pre[dq[tail - 1]] <= val) tail--;
          dq[tail++] = add;
        }
        while (tail > head && dq[head] < i - r) head++;
        long v = dp[j][i - 1];
        if (tail > head) v = Math.max(v, pre[i] + dp[j - 1][dq[head]] - pre[dq[head]]);
        dp[j][i] = v;
      }
      best = Math.max(best, dp[j][n]);
    }
    return best;
  }
}
